public class Main {
    public static void main(String[] args) {
        for (int i = 2; i <= 20; i += 2) {
            System.out.println(i);
        }

        int count = 5;
        while (count > 0) {
            System.out.println(count);
            count--;
        }
        System.out.println("Liftoff!");
    }
}

