java-arrays.sample_answer:
public class Main {
    public static void main(String[] args) {
        double[] temps = {31.5, 29.0, 33.2, 30.1, 28.7};
        double highest = temps[0];

        for (double t : temps) {
            if (t > highest) {
                highest = t;
            }
        }

        System.out.println("Highest: " + highest);
    }
}

