java-methods.sample_answer:
public class Main {
    static String grade(int score) {
        if (score >= 90) {
            return "A";
        } else if (score >= 80) {
            return "B";
        } else if (score >= 75) {
            return "C";
        }
        return "F";
    }

    public static void main(String[] args) {
        System.out.println(grade(92));
        System.out.println(grade(84));
        System.out.println(grade(60));
    }
}

